from django.contrib import admin
from .models import Attempt, AttemptQuestion, StudentResponse, Grade, GradeItem, GradingEvent
# Sensitive data is not exposed through blanket autogenerated admin forms.
@admin.register(Attempt)
class AttemptAdmin(admin.ModelAdmin):
    list_display = ("id", "student", "state", "started_at", "submitted_at")
    readonly_fields = ("student", "exam_version", "state", "started_at", "deadline_at", "submitted_at")
    def has_add_permission(self, request): return False
    def has_change_permission(self, request, obj=None): return False
    def has_delete_permission(self, request, obj=None): return False

@admin.register(Grade)
class GradeAdmin(admin.ModelAdmin):
    list_display = ("attempt", "scored_marks", "scored_possible_marks", "ungraded_possible_marks", "final_percentage")
    readonly_fields = ("attempt", "scored_marks", "scored_possible_marks", "ungraded_possible_marks", "final_percentage", "finalized_at")
    def has_add_permission(self, request): return False
    def has_change_permission(self, request, obj=None): return False
    def has_delete_permission(self, request, obj=None): return False
